SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `player_levelstats`;
CREATE TABLE `player_levelstats` (
  `race` tinyint(3) unsigned NOT NULL,
  `class` tinyint(3) unsigned NOT NULL,
  `level` tinyint(3) unsigned NOT NULL,
  `str` smallint(4) unsigned NOT NULL,
  `agi` smallint(4) unsigned NOT NULL,
  `sta` smallint(4) unsigned NOT NULL,
  `inte` smallint(4) unsigned NOT NULL,
  `spi` smallint(4) unsigned NOT NULL,
  PRIMARY KEY (`race`,`class`,`level`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Stores levels stats.';













































































































































































